  <section class="pub-section" id="competitors"><h2 class="pub-section-title">Competitor watchlist</h2><p>Record only public/native metrics with the source and observation date. This is benchmarking, not covert monitoring.</p><div class="experience-grid"><?php foreach($competitors as$r):?><article class="experience-card"><h3><?=e($r['name'])?></h3><p><?=e($platforms[$r['platform']]??$r['platform'])?> · <?=e($r['observed_at'])?></p><dl><?php foreach(($r['metrics']??[])as$k=>$v):?><dt><?=e(ucwords(str_replace('_',' ',$k)))?></dt><dd><?=number_format((int)$v)?></dd><?php endforeach;?></dl><p class="muted"><?=e($r['source'])?></p><a href="<?=e($r['url'])?>" target="_blank" rel="noopener noreferrer">Open public profile ↗</a></article><?php endforeach;?></div><details><summary>Add competitor snapshot</summary><form method="post" action="<?=url('/write/social-operations/competitor')?>"><?=csrf_field()?><label>Platform<select name="platform" required><?php foreach($platforms as$slug=>$name):?><option value="<?=e($slug)?>"><?=e($name)?></option><?php endforeach;?></select></label><label>Public account name<input name="name" maxlength="160" required></label><label>Public profile URL<input type="url" name="url" placeholder="https://" required></label><div class="program-fields"><label>Followers<input type="number" min="0" step="1" name="followers"></label><label>Posts in period<input type="number" min="0" step="1" name="posts"></label><label>Engagements<input type="number" min="0" step="1" name="engagements"></label><label>Views<input type="number" min="0" step="1" name="views"></label></div><label>Source and period<textarea name="source" maxlength="500" required></textarea></label><button class="wbtn primary">Save competitor snapshot</button></form></details></section>

  <section class="pub-section" id="hashtags"><h2 class="pub-section-title">Hashtag & topic tracking</h2><p>Track public topic signals without pretending they represent the whole platform.</p><div class="experience-grid"><?php foreach($hashtags as$r):?><article class="experience-card"><h3><?=e($r['hashtag'])?></h3><p><?=e($platforms[$r['platform']]??$r['platform'])?> · <?=e($r['observed_at'])?></p><dl><?php foreach(($r['metrics']??[])as$k=>$v):?><dt><?=e(ucwords(str_replace('_',' ',$k)))?></dt><dd><?=number_format((int)$v)?></dd><?php endforeach;?></dl><p class="muted"><?=e($r['source'])?></p></article><?php endforeach;?></div><details><summary>Add hashtag/topic snapshot</summary><form method="post" action="<?=url('/write/social-operations/hashtag')?>"><?=csrf_field()?><label>Platform<select name="platform" required><?php foreach($platforms as$slug=>$name):?><option value="<?=e($slug)?>"><?=e($name)?></option><?php endforeach;?></select></label><label>Hashtag or topic token<input name="hashtag" maxlength="100" placeholder="#socialenterprise" required></label><div class="program-fields"><label>Observed posts<input type="number" min="0" step="1" name="posts"></label><label>Observed views<input type="number" min="0" step="1" name="views"></label><label>Observed reach<input type="number" min="0" step="1" name="reach"></label><label>Observed engagements<input type="number" min="0" step="1" name="engagements"></label></div><label>Source and period<textarea name="source" maxlength="500" required></textarea></label><button class="wbtn primary">Save hashtag snapshot</button></form></details></section>

