  <section class="pub-section" id="smartlinks"><h2 class="pub-section-title">SmartLinks / link in bio</h2><p>Manage a first-party bio-link page at <a href="<?=url('/links')?>" target="_blank" rel="noopener noreferrer"><?=e(url('/links'))?></a>.</p><form method="post" action="<?=url('/write/social-operations/smartlinks')?>"><?=csrf_field()?><div class="pub-list"><?php foreach(array_pad($smartlinks,8,[])as$idx=>$row):?><article class="pub-row"><div><label>Label<input name="links[<?=$idx?>][label]" maxlength="80" value="<?=e($row['label']??'')?>"></label><label>HTTPS URL<input type="url" name="links[<?=$idx?>][url]" value="<?=e($row['url']??'')?>"></label></div><div class="pub-row-meta"><?php if(!empty($row['id'])):?><span><?=intval($smartlinkClicks[$row['id']]['count']??0)?> clicks</span><?php endif;?><label><input type="checkbox" name="links[<?=$idx?>][enabled]" value="1" <?=!empty($row['enabled'])?'checked':''?>> Visible</label></div></article><?php endforeach;?></div><button class="wbtn primary">Save SmartLinks</button></form></section>

